#!/bin/bash
# Fix Gradle files generated by flutter create for Flutter 3.47.5 + Gradle 9.x compatibility.
cd android

# 1. Fix readWithUTF8 (removed in Gradle 9) in all Gradle files
find . -name "*.gradle" -o -name "*.kts" | while read f; do
    if grep -q "readWithUTF8" "$f" 2>/dev/null; then
        # Replace readWithUTF8('UTF-8') with withReader('UTF-8') { ... load(it) }
        sed -i "s/localPropertiesFile.readWithUTF8('UTF-8')/localPropertiesFile.withReader('UTF-8') { localProperties.load(it) }/" "$f"
        # Remove the now-redundant localProperties.load(localPropertiesFile) line
        sed -i "/localProperties.load(localPropertiesFile)/d" "$f"
    fi
done

# 2. Ensure project-level build.gradle.kts has buildscript with AGP
if ! grep -q "buildscript" build.gradle.kts 2>/dev/null; then
    cat > build.gradle.kts << 'EOF'
buildscript {
    repositories {
        google()
        mavenCentral()
    }
    dependencies {
        classpath("com.android.tools.build:gradle:9.1.0")
        classpath("org.jetbrains.kotlin:kotlin-gradle-plugin:2.2.20")
    }
}

allprojects {
    repositories {
        google()
        mavenCentral()
    }
}

val newBuildDir: Directory =
    rootProject.layout.buildDirectory
        .dir("../../build")
        .get()
rootProject.layout.buildDirectory.value(newBuildDir)

subprojects {
    val newSubprojectBuildDir: Directory = newBuildDir.dir(project.name)
    project.layout.buildDirectory.value(newSubprojectBuildDir)
}
subprojects {
    project.evaluationDependsOn(":app")
}

tasks.register<Delete>("clean") {
    delete(rootProject.layout.buildDirectory)
}
EOF
fi

# 3. Rewrite app/build.gradle with plugins block (declarative Flutter plugin)
cat > app/build.gradle << 'GRADLE_EOF'
plugins {
    id 'com.android.application'
    id 'org.jetbrains.kotlin.android'
    id 'dev.flutter.flutter-gradle-plugin' version '3.47.5'
}

def localProperties = new Properties()
def localPropertiesFile = rootProject.file('local.properties')
if (localPropertiesFile.exists()) {
    localPropertiesFile.withReader('UTF-8') { reader ->
        localProperties.load(reader)
    }
}
def flutterRoot = localProperties.getProperty('flutter.sdk')
if (flutterRoot == null) {
    throw new GradleException("Flutter SDK not found. Define location with flutter.sdk in the local.properties file.")
}
def flutterVersionCode = localProperties.getProperty('flutterVersionCode')
if (flutterVersionCode == null) {
    flutterVersionCode = '1'
}
def flutterVersionName = localProperties.getProperty('flutterVersionName')
if (flutterVersionName == null) {
    flutterVersionName = '1.0.0'
}

android {
    namespace = "com.helix.helix"
    compileSdkVersion flutter.compileSdkVersion
    ndkVersion flutter.ndkVersion

    compileOptions {
        sourceCompatibility JavaVersion.VERSION_1_8
        targetCompatibility JavaVersion.VERSION_1.8
    }

    kotlinOptions {
        jvmTarget = '1.8'
    }

    sourceSets {
        main.java.srcDirs += 'src/main/kotlin'
    }

    defaultConfig {
        applicationId "com.helix.helix"
        minSdkVersion flutter.minSdkVersion
        targetSdkVersion flutter.targetSdkVersion
        versionCode flutterVersionCode.toInteger()
        versionName flutterVersionName
    }

    buildTypes {
        release {
            signingConfig signingConfigs.debug
        }
    }
}

flutter {
    source '../..'
}

dependencies {
    implementation "org.jetbrains.kotlin:kotlin-stdlib-jdk8:2.2.20"
    implementation "androidx.core:core-ktx:+"
    implementation "androidx.annotation:annotation:+"
    implementation "androidx.lifecycle:lifecycle-runtime-ktx:+"
    implementation "androidx.activity:activity:+"
}
GRADLE_EOF

echo "Gradle files fixed successfully"
